#!/usr/bin/perl
use strict; use warnings;

my $root = "/bench/repo";
chdir $root or die;

# --- collect all .go files ---
my @allgo = split /\n/, `find . -name '*.go' -not -path './web/*' -not -path './node_modules/*'`;

# --- read every file once ---
my %content; my %lines;
for my $f (@allgo) {
    open my $fh, '<', $f or next;
    local $/; my $c = <$fh>; close $fh;
    $content{$f} = $c;
    $lines{$f} = [split /\n/, $c];
}

# --- collect declarations under internal/ (non-test) ---
# record: name, recv type, package, file, line
my @decls;
for my $f (@allgo) {
    next unless $f =~ m{^\./internal/};
    next if $f =~ /_test\.go$/;
    my $pkg = ($content{$f} =~ /^package\s+(\w+)/m) ? $1 : '?';
    my $ln = 0;
    for my $l (@{$lines{$f}}) {
        $ln++;
        if ($l =~ /^func\s+\(\s*\w+\s+\*?([\w\[\]]+)\s*\)\s+(\w+)\s*\(/) {
            push @decls, { name=>$2, recv=>$1, pkg=>$pkg, file=>$f, line=>$ln };
        } elsif ($l =~ /^func\s+(\w+)\s*\(/) {
            push @decls, { name=>$1, recv=>'', pkg=>$pkg, file=>$f, line=>$ln };
        }
    }
}

print "total decls: ".scalar(@decls)."\n";

# --- count call sites ---
my @out;
for my $d (@decls) {
    my $n = $d->{name};
    next if $n eq 'init' || $n eq 'main';
    my ($calls, $tcalls) = (0,0);
    my %callerfiles;
    for my $f (@allgo) {
        my $ln = 0;
        for my $l (@{$lines{$f}}) {
            $ln++;
            next if $f eq $d->{file} && $ln == $d->{line};   # skip the decl itself
            next if $l =~ /^\s*(//|\*)/;                      # skip comments
            my $hit = 0;
            if ($d->{recv} ne '') {
                # method: any selector call .Name(
                $hit = 1 if $l =~ /\.\Q$n\E\s*\(/;
            } else {
                if ($l =~ /\b\Q$d->{pkg}\E\.\Q$n\E\s*\(/) { $hit = 1 }
                # same-package bare call
                elsif ($l !~ /\.\s*\Q$n\E\s*\(/ && $l =~ /(?<![\w.])\Q$n\E\s*\(/) {
                    my $samepkg = 0;
                    if ($content{$f} =~ /^package\s+\Q$d->{pkg}\E\s*$/m) { $samepkg = 1 }
                    $hit = 1 if $samepkg;
                }
            }
            next unless $hit;
            # skip other declaration lines of same name
            next if $l =~ /^func\s/;
            if ($f =~ /_test\.go$/) { $tcalls++ } else { $calls++; $callerfiles{$f}=1 }
        }
    }
    push @out, { %$d, calls=>$calls, tcalls=>$tcalls, files=>scalar(keys %callerfiles) };
}

@out = sort { $b->{calls} <=> $a->{calls} } @out;
printf("%-6s %-6s %-6s %-28s %-14s %s\n", "prod", "test", "files", "symbol", "recv", "file");
for my $o (@out[0..49]) {
    last unless $o;
    printf("%-6d %-6d %-6d %-28s %-14s %s:%d\n", $o->{calls}, $o->{tcalls}, $o->{files},
        $o->{name}, ($o->{recv}||"-"), $o->{file}, $o->{line});
}

